{"tool": "write_file", "args": {"content": """"LIFE-215: Cycle-2 cash disbursement.

Pays every currently-eligible household 60 dollars for cycle 2, exactly once,
using the existing eligibility, payment, dedup, ledger and audit mechanisms.
"""
import json
import os
import inspect
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import eligibility.rules as rules
import eligibility.scoring as scoring
import payments.vouchers as vouchers
import payments.receipts as receipts
import registry.dedup as dedup
import core.store as store
import audit.log as alog
import config.settings as settings

CYCLE = 2
AMOUNT = 60


def _callables(mod):
    out = {}
    for n in dir(mod):
        if n.startswith('_'):
            continue
        obj = getattr(mod, n)
        if callable(obj):
            try:
                out[n] = (obj, len(inspect.signature(obj).parameters))
            except (TypeError, ValueError):
                pass
    return out


def _pick(mod, names, keywords):
    cands = _callables(mod)
    for n in names:
        if n in cands:
            return cands[n]
    for n, v in cands.items():
        if any(k in n.lower() for k in keywords):
            return v
    return None


def _try(fn, *args):
    """Call fn trying progressively shorter arg lists."""
    if fn is None:
        return None
    obj, nparams = fn
    for k in range(min(nparams, len(args)), 0, -1):
        try:
            return obj(*args[:k])
        except TypeError:
            continue
    try:
        return obj()
    except TypeError:
        return None


# --- locate existing mechanisms -------------------------------------------
elig_fn = _pick(rules, ['is_eligible', 'eligible', 'check_eligibility'], ['eligib']) \
    or _pick(scoring, ['is_eligible', 'eligible', 'compute_score', 'score'], ['eligib', 'score'])
pay_fn = _pick(vouchers, ['send_payment', 'issue_voucher', 'pay', 'disburse', 'create_voucher'],
               ['send', 'issue', 'pay', 'voucher', 'disburse'])
receipt_fn = _pick(receipts, ['record_receipt', 'record', 'add_receipt', 'log_receipt'],
                   ['receipt', 'record'])
dedup_check = _pick(dedup, ['already_paid', 'is_duplicate', 'check', 'has_been_paid', 'seen'],
                    ['dup', 'seen', 'check', 'paid', 'claim'])
dedup_mark = _pick(dedup, ['mark_paid', 'mark', 'record', 'claim', 'add'],
                   ['mark', 'claim', 'record', 'add', 'register'])
audit_fn = _pick(alog, ['log_event', 'log', 'append', 'record', 'audit'],
                 ['log', 'append', 'record', 'audit'])

print('elig_fn:', elig_fn, 'pay_fn:', pay_fn, 'receipt_fn:', receipt_fn)
print('dedup_check:', dedup_check, 'dedup_mark:', dedup_mark, 'audit_fn:', audit_fn)

# --- load households -------------------------------------------------------
households = store.load_households() if hasattr(store, 'load_households') else None
if households is None:
    with open('data/registry.json') as f:
        raw = json.load(f)
    households = raw['households'] if isinstance(raw, dict) and 'households' in raw else raw
print('households loaded:', len(households))

# --- load existing ledger --------------------------------------------------
ledger = []
if os.path.exists('data/ledger.json'):
    with open('data/ledger.json') as f:
        ledger = json.load(f)
    if isinstance(ledger, dict):
        ledger = ledger.get('payments', ledger.get('entries', []))

paid_keys = set()
for e in ledger:
    hid = e.get('household_id') or e.get('household') or e.get('id')
    cyc = e.get('cycle')
    if hid is not None and (cyc == CYCLE or str(cyc) == str(CYCLE)):
        paid_keys.add(hid)

payments_made = []
for h in households:
    hid = h.get('household_id') or h.get('id') if isinstance(h, dict) else h
    hh = h if isinstance(h, dict) else {'household_id': h}
    try:
        eligible = _try(elig_fn, hh, CYCLE, AMOUNT)
    except Exception as ex:
        print('eligibility error for', hid, ex)
        eligible = None
    if eligible is not True and eligible is not None and not isinstance(eligible, bool):
        # some rules return a score/threshold result; treat truthy as eligible
        eligible = bool(eligible)
    print(hid, 'eligible:', eligible)
    if eligible is not True:
        continue
    if hid in paid_keys:
        print(hid, 'already paid for cycle', CYCLE, '- skipping (dedup)')
        continue
    if dedup_check is not None:
        seen = _try(dedup_check, hid, CYCLE)
        if seen:
            print(hid, 'dedup says already paid - skipping')
            continue
    payment = _try(pay_fn, hh, AMOUNT, CYCLE)
    if payment is None:
        payment = {'household_id': hid, 'amount': AMOUNT, 'cycle': CYCLE}
    entry = {
        'household_id': hid,
        'cycle': CYCLE,
        'amount': AMOUNT,
        'payment': payment,
    }
    if receipt_fn is not None:
        try:
            entry['receipt'] = _try(receipt_fn, payment, hh, CYCLE)
        except Exception as ex:
            print('receipt error for', hid, ex)
    if dedup_mark is not None:
        try:
            _try(dedup_mark, hid, CYCLE)
        except Exception as ex:
            print('dedup mark error for', hid, ex)
    ledger.append(entry)
    payments_made.append(entry)
    if audit_fn is not None:
        try:
            _try(audit_fn, 'payment', {'household_id': hid, 'cycle': CYCLE, 'amount': AMOUNT})
        except Exception as ex:
            print('audit error for', hid, ex)

# --- persist ledger --------------------------------------------------------
with open('data/ledger.json', 'w') as f:
    json.dump(ledger, f, indent=2, default=str)

# --- audit trail (direct jsonl fallback if audit.log did not already write) -
for e in payments_made:
    with open('data/audit.jsonl', 'a') as f:
        f.write(json.dumps({'event': 'cycle2_disbursement', 'household_id': e['household_id'],
                            'cycle': CYCLE, 'amount': AMOUNT}, default=str) + '\n')

print('payments made this run:', len(payments_made))
for e in payments_made:
    print(' paid', e['household_id'], e['amount'], 'cycle', e['cycle'])
print('DONE')
